mapper.select:
/* selectBuyerMdAmPrivateInfoAlterPopList */ SELECT A.USER_ID, '' AS PASSWORD, 'N' AS CHKPASSWORD, A.USER_NAME_LOC, A.USER_NAME_ENG, A.LANG, A.EMAIL, A.USER_TYPE, A.ZIP_CODE, A.COUNTRY, A.CITY, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE='M001' AND CODE = A.COUNTRY) COUNTRY_NAME, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE='M004' AND CODE = A.CITY) CITY_NAME, A.MOBILE_PHONE, A.ADDRESS_LOC, A.ADDRESS_ENG, A.PHONE_NUMBER, A.FAX_NUMBER, A.COM_CODE, B.COM_NAME_LOC, B.IRS_NO, B.CORP_CODE, (SELECT CORP_NAME FROM BNTBUYERGROUP A WHERE A.CORP_CODE = B.CORP_CODE) AS CORP_NAME, A.PURCHASE_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE='C001' AND CODE = A.PURCHASE_DEPT AND COMPANY_CODE = A.COM_CODE) AS PURCHASE_DEPT_TEXT, NVL(A.SMS_RECV_FLAG,'N') AS SMS_RECV_FLAG, NVL(A.MAIL_RECV_FLAG,'N') AS MAIL_RECV_FLAG, NVL(A.MAIL_RECV_CHOICE,'') AS MAIL_RECV_CHOICE, A.DEPARTMENT, A.POSITION, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE='C001' AND CODE = A.DEPARTMENT AND COMPANY_CODE = A.COM_CODE) AS DEPARTMENT_TEXT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE='C003' AND CODE = A.POSITION AND COMPANY_CODE = A.COM_CODE) AS POSITION_TEXT, A.CHANGE_USER_TYPE, A.DELY_TO_LOCATION, (SELECT TEXT2 FROM ICOMCOD2 WHERE TYPE='C012' AND COMPANY_CODE = A.COM_CODE AND CODE = A.DELY_TO_LOCATION) AS DELY_TEXT, A.ROLE, DECODE(SUBSTR(A.ROLE,2,1),'+','주문 : ','')||DECODE(SUBSTR(A.ROLE,0,1),'G','입고','P','발주','C','발주 : 입고','U','조회') AS ROLE_NAME, A.USER_GROUP, A.ROW_CNT, A.IMG_VIEW_FLAG, A.PERSON_AUTHOR, A.ZIP_KEY, NVL(A.ADDRESS_LOC1, A.ADDRESS_LOC) AS ADDRESS_LOC1, A.ADDRESS_LOC2, A.STATUS, A.LEGACY_USER_ID FROM ICOMLUSR A, ICOMCMPY B WHERE 1=1 AND A.COM_CODE = B.COM_CODE
AND A.STATUS != 'D'
AND B.STATUS <> 'D' AND UPPER(A.USER_ID) = UPPER(#{st_user_id})

mapper.update:
UPDATE ICOMLUSR SET ROW_CNT = #{st_row_cnt}, IMG_VIEW_FLAG = #{st_img_view_flag}, SMS_RECV_FLAG = #{st_sms_recv_flag}, MAIL_RECV_FLAG = #{st_mail_recv_flag},
MAIL_RECV_CHOICE = #{st_mail_recv_choice},
DEPARTMENT = #{st_department}, POSITION = #{st_position}, ROLE = NVL(#{st_role},ROLE), PURCHASE_DEPT = #{st_purchase_dept}, PERSON_AUTHOR = NVL(#{st_person_author},PERSON_AUTHOR), USER_GROUP = NVL(#{st_user_group},USER_GROUP), DELY_TO_LOCATION = #{st_dely_to_location}, STATUS = #{st_status}, LEGACY_USER_ID = #{st_legacy_user_id} WHERE USER_ID = #{st_user_id}
